#include "library/EventRepository.h"
#include <QDir>
#include <QFileInfo>
#include <QSqlDatabase>
#include <QSqlQuery>
#include <QUuid>
#include <algorithm>

namespace churchpresenter {
EventRepository::EventRepository(QString p):m_databasePath(std::move(p)){}
EventRepository::~EventRepository(){if(m_connectionName.isEmpty())return;{auto d=QSqlDatabase::database(m_connectionName,false);if(d.isValid())d.close();}QSqlDatabase::removeDatabase(m_connectionName);}
bool EventRepository::open(){if(!m_connectionName.isEmpty()&&QSqlDatabase::database(m_connectionName,false).isOpen())return true;if(!QDir().mkpath(QFileInfo(m_databasePath).absolutePath()))return false;m_connectionName="holyscreen-events-"+QUuid::createUuid().toString(QUuid::WithoutBraces);auto d=QSqlDatabase::addDatabase("QSQLITE",m_connectionName);d.setDatabaseName(m_databasePath);if(!d.open())return false;QSqlQuery q(d);if(!q.exec("PRAGMA foreign_keys=ON"))return false;if(!q.exec("CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,title TEXT NOT NULL,scheduled_at TEXT NOT NULL DEFAULT '')"))return false;return q.exec("CREATE TABLE IF NOT EXISTS playlist_items(id TEXT PRIMARY KEY,event_id TEXT NOT NULL,item_type INTEGER NOT NULL,reference_id TEXT NOT NULL,title TEXT NOT NULL,duration_ms INTEGER NOT NULL DEFAULT 0,position INTEGER NOT NULL,FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE)");}
QVector<Event> EventRepository::events()const{QVector<Event>r;QSqlQuery q(QSqlDatabase::database(m_connectionName,false));if(q.exec("SELECT id,title,scheduled_at FROM events ORDER BY scheduled_at DESC,title COLLATE NOCASE"))while(q.next())r.append({q.value(0).toString(),q.value(1).toString(),q.value(2).toString()});return r;}
Event EventRepository::event(const QString&id)const{QSqlQuery q(QSqlDatabase::database(m_connectionName,false));q.prepare("SELECT id,title,scheduled_at FROM events WHERE id=:id");q.bindValue(":id",id);return q.exec()&&q.next()?Event{q.value(0).toString(),q.value(1).toString(),q.value(2).toString()}:Event{};}
QString EventRepository::saveEvent(Event e){if(m_connectionName.isEmpty()&&!open())return{};if(e.id.isEmpty())e.id=QUuid::createUuid().toString(QUuid::WithoutBraces);if(e.title.trimmed().isEmpty())e.title="Novo culto";if(e.scheduledAt.isNull())e.scheduledAt="";QSqlQuery q(QSqlDatabase::database(m_connectionName,false));q.prepare("INSERT INTO events VALUES(:id,:title,:at) ON CONFLICT(id) DO UPDATE SET title=excluded.title,scheduled_at=excluded.scheduled_at");q.bindValue(":id",e.id);q.bindValue(":title",e.title);q.bindValue(":at",e.scheduledAt);return q.exec()?e.id:QString{};}
bool EventRepository::removeEvent(const QString&id){QSqlQuery q(QSqlDatabase::database(m_connectionName,false));q.prepare("DELETE FROM events WHERE id=:id");q.bindValue(":id",id);return q.exec()&&q.numRowsAffected()==1;}
QVector<PlaylistItem> EventRepository::items(const QString&e)const{QVector<PlaylistItem>r;QSqlQuery q(QSqlDatabase::database(m_connectionName,false));q.prepare("SELECT id,item_type,reference_id,title,duration_ms,position FROM playlist_items WHERE event_id=:id ORDER BY position,id");q.bindValue(":id",e);if(q.exec())while(q.next())r.append({q.value(0).toString(),static_cast<PlaylistItemType>(q.value(1).toInt()),q.value(2).toString(),q.value(3).toString(),q.value(4).toLongLong(),q.value(5).toInt()});return r;}
bool EventRepository::addItem(const QString&e,PlaylistItem i){if(event(e).id.isEmpty()||i.referenceId.isEmpty())return false;if(i.id.isEmpty())i.id=QUuid::createUuid().toString(QUuid::WithoutBraces);if(i.title.isNull())i.title="";QSqlQuery p(QSqlDatabase::database(m_connectionName,false));p.prepare("SELECT COALESCE(MAX(position),-1)+1 FROM playlist_items WHERE event_id=:id");p.bindValue(":id",e);if(!p.exec()||!p.next())return false;QSqlQuery q(QSqlDatabase::database(m_connectionName,false));q.prepare("INSERT INTO playlist_items VALUES(:id,:event,:type,:ref,:title,:duration,:position)");q.bindValue(":id",i.id);q.bindValue(":event",e);q.bindValue(":type",static_cast<int>(i.type));q.bindValue(":ref",i.referenceId);q.bindValue(":title",i.title);q.bindValue(":duration",i.durationMs);q.bindValue(":position",p.value(0));return q.exec();}
bool EventRepository::removeItem(const QString&id){QSqlQuery get(QSqlDatabase::database(m_connectionName,false));get.prepare("SELECT event_id FROM playlist_items WHERE id=:id");get.bindValue(":id",id);if(!get.exec()||!get.next())return false;const auto e=get.value(0).toString();QSqlQuery q(QSqlDatabase::database(m_connectionName,false));q.prepare("DELETE FROM playlist_items WHERE id=:id");q.bindValue(":id",id);return q.exec()&&normalize(e);}
bool EventRepository::moveItem(const QString&id,int index){QSqlQuery get(QSqlDatabase::database(m_connectionName,false));get.prepare("SELECT event_id FROM playlist_items WHERE id=:id");get.bindValue(":id",id);if(!get.exec()||!get.next())return false;const auto e=get.value(0).toString();auto list=items(e);auto it=std::find_if(list.begin(),list.end(),[&](const auto&i){return i.id==id;});if(it==list.end())return false;auto value=*it;list.erase(it);index=std::clamp(index,0,static_cast<int>(list.size()));list.insert(index,value);auto db=QSqlDatabase::database(m_connectionName,false);if(!db.transaction())return false;QSqlQuery q(db);q.prepare("UPDATE playlist_items SET position=:p WHERE id=:id");for(int n=0;n<list.size();++n){q.bindValue(":p",n);q.bindValue(":id",list[n].id);if(!q.exec()){db.rollback();return false;}}return db.commit();}
qint64 EventRepository::totalDurationMs(const QString&e)const{QSqlQuery q(QSqlDatabase::database(m_connectionName,false));q.prepare("SELECT COALESCE(SUM(duration_ms),0) FROM playlist_items WHERE event_id=:id");q.bindValue(":id",e);return q.exec()&&q.next()?q.value(0).toLongLong():0;}
bool EventRepository::normalize(const QString&e){const auto list=items(e);QSqlQuery q(QSqlDatabase::database(m_connectionName,false));q.prepare("UPDATE playlist_items SET position=:p WHERE id=:id");for(int n=0;n<list.size();++n){q.bindValue(":p",n);q.bindValue(":id",list[n].id);if(!q.exec())return false;}return true;}
}
